// Resolves running WLED/Tubes reports without weakening USB board-proof rules.
// AI: below section was generated by an AI
export function resolveRunningDeviceIdentity({ info, config }, target) {
	const release = String(info?.release || info?.tubes?.release || "").toUpperCase();
	const family = String(info?.hardwareFamily || info?.tubes?.hardwareFamily || "").toLowerCase();
	const variant = String(info?.hardwareVariant || info?.tubes?.hardwareVariant || "").toUpperCase();
	const arch = String(info?.arch || "").toLowerCase();
	const exactRelease = release === "DIG2GO_TUBES";
	const exactFamily = family === target.hardwareFamily;
	const exactVariant = variant === "DIG2GO_TUBES" || variant === "DIG2GO";
	if (arch && arch !== "esp32") return { matched:false, proof:"running-device-report", reason:"wrong-chip-family" };
	if (exactRelease && (exactFamily || exactVariant)) return { matched:true, proof:"running-device-report", targetId:target.hardwareFamily };
	return { matched:false, proof:"running-device-report", reason:"identity-not-exact", observed:{ release, family, variant, hasConfig:Boolean(config) } };
}

export async function inspectRunningDevice(baseUrl, fetchImpl, target) {
	const base = new URL(baseUrl);
	if (!new Set(["http:", "https:"]).has(base.protocol)) throw new Error("Unsupported device address");
	const [infoResponse, configResponse] = await Promise.all([fetchImpl(new URL("/json/si", base)), fetchImpl(new URL("/json/cfg", base))]);
	if (!infoResponse.ok || !configResponse.ok) throw new Error("Running controller identity is unavailable");
	return resolveRunningDeviceIdentity({ info:await infoResponse.json(), config:await configResponse.json() }, target);
}
